-- Gold layer: star schema that feeds the KPIs, the API and the dashboard.
-- Built from silver by pipeline/build_gold.py.

CREATE SCHEMA IF NOT EXISTS gold;

-- One row per calendar day (course Week4 pattern). The range comes from the
-- data and is filled in by the transform. These rows are generated by our own
-- SQL, not read from a source, so CHECK constraints are safe: a failure would
-- be a bug in our code and should fail loudly.
CREATE TABLE IF NOT EXISTS gold.dim_date (
    date_key        INTEGER      PRIMARY KEY,      -- e.g. 20250918
    full_date       DATE         NOT NULL UNIQUE,
    year            SMALLINT     NOT NULL,
    quarter         SMALLINT     NOT NULL CHECK (quarter BETWEEN 1 AND 4),
    month           SMALLINT     NOT NULL CHECK (month BETWEEN 1 AND 12),
    month_name      VARCHAR(10)  NOT NULL,          -- 'January' … 'December'
    week_of_year    SMALLINT     NOT NULL,          -- ISO week 1-53
    day_of_week     SMALLINT     NOT NULL CHECK (day_of_week BETWEEN 0 AND 6), -- 0=Sun
    day_name        VARCHAR(10)  NOT NULL,          -- 'Sunday' … 'Saturday'
    is_weekend      BOOLEAN      NOT NULL
);

-- One row per employee, SCD Type 1: attributes are overwritten in place and
-- no history is kept. Column selection is by analytical purpose, confirmed by
-- the data provider: personal and de-identified fields stay in silver only, so
-- gold, which feeds dashboards, carries no personal data it does not need.
-- Employees seen only in timesheets get an inferred row (is_inferred = true)
-- with every attribute NULL, so all facts can join to an employee.
CREATE TABLE IF NOT EXISTS gold.dim_employee (
    -- GENERATED ALWAYS rejects hand-set keys, which keeps the keys stable
    employee_key           INTEGER       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    client_employee_id     TEXT          NOT NULL UNIQUE,   -- natural key
    first_name             TEXT,                            -- readable label for drill-downs
    job_code               TEXT,
    job_title              TEXT,
    job_start_date         DATE,
    organization_name      TEXT,
    department_id          TEXT,
    department_name        TEXT,
    fte_status             TEXT,
    scheduled_weekly_hour  NUMERIC(5,2),
    manager_employee_id    TEXT,
    hire_date              DATE,
    recent_hire_date       DATE,
    term_date              DATE,
    active_status          BOOLEAN,
    termination_reason     TEXT,
    is_per_diem            BOOLEAN,                         -- NULL for inferred: unknown, not false
    is_inferred            BOOLEAN       NOT NULL,

    -- Employee-file row this came from; NULL for inferred employees
    source_file            TEXT,
    source_row_num         INTEGER,
    created_at             TIMESTAMPTZ   NOT NULL DEFAULT now(),  -- set on insert, never changed
    updated_at             TIMESTAMPTZ   NOT NULL DEFAULT now(),  -- set only when values change

    -- Written only by our own transform, so safe to enforce: a real employee
    -- always has lineage, an inferred one never does.
    CHECK (is_inferred = (source_file IS NULL))
);

-- One row per punch, the same grain as silver.timesheet. Rebuilt on every run,
-- so there is no surrogate key: it would be renumbered each time, while the
-- natural key (employee, punch-in) is stable.
CREATE TABLE IF NOT EXISTS gold.fact_timesheet (
    employee_key              INTEGER       NOT NULL REFERENCES gold.dim_employee (employee_key),
    date_key                  INTEGER       NOT NULL REFERENCES gold.dim_date (date_key),  -- from punch_apply_date

    client_employee_id        TEXT          NOT NULL,
    department_id             TEXT,
    department_name           TEXT,
    home_department_id        TEXT,
    home_department_name      TEXT,
    pay_code                  TEXT,
    punch_in_comment          TEXT,
    punch_out_comment         TEXT,
    hours_worked              NUMERIC(5,2),
    punch_apply_date          DATE,
    punch_in_datetime         TIMESTAMP     NOT NULL,
    punch_out_datetime        TIMESTAMP,
    scheduled_start_datetime  TIMESTAMP,
    scheduled_end_datetime    TIMESTAMP,

    -- Bronze row this punch came from, carried through silver
    source_file               TEXT          NOT NULL,
    source_row_num            INTEGER       NOT NULL,
    loaded_at                 TIMESTAMPTZ   NOT NULL DEFAULT now(),

    PRIMARY KEY (employee_key, punch_in_datetime)
);

-- Date-range filters (KPIs, the API). Lookups by employee already use the
-- primary key index, whose first column is employee_key.
CREATE INDEX IF NOT EXISTS fact_timesheet_date_key_idx
    ON gold.fact_timesheet (date_key);

-- Average working hours per employee per day worked. Hours are summed per
-- employee per day first, because one person can have several punches in a
-- day. All pay codes count as worked hours until pay codes are categorized
-- in the cleaning step.
CREATE OR REPLACE VIEW gold.kpi_avg_daily_hours AS
WITH daily AS (
    SELECT employee_key, date_key, SUM(hours_worked) AS daily_hours
    FROM gold.fact_timesheet
    GROUP BY employee_key, date_key
)
SELECT
    e.employee_key,
    e.client_employee_id,
    e.is_inferred,
    COUNT(*)                      AS days_worked,
    ROUND(AVG(d.daily_hours), 2)  AS avg_daily_hours
FROM daily AS d
JOIN gold.dim_employee AS e USING (employee_key)
GROUP BY e.employee_key, e.client_employee_id, e.is_inferred;
